    /**
     * Bidirectional type of the unassigned code points of the blocks whose default
     * type is not L, as [first code point, last code point, type].
     *
     * @var array<int, array{int, int, string}>
     */
    public const DEFAULT_RANGES = [
        [0x0590,   0x05FF,   'R'],
        [0x0600,   0x07BF,   'AL'],
        [0x07C0,   0x085F,   'R'],
        [0x0860,   0x08FF,   'AL'],
        [0x20A0,   0x20CF,   'ET'],
        [0xFB1D,   0xFB4F,   'R'],
        [0xFB50,   0xFDCF,   'AL'],
        [0xFDF0,   0xFDFF,   'AL'],
        [0xFE70,   0xFEFF,   'AL'],
        [0x1_0800, 0x1_0CFF, 'R'],
        [0x1_0D00, 0x1_0D3F, 'AL'],
        [0x1_0D40, 0x1_0EBF, 'R'],
        [0x1_0EC0, 0x1_0EFF, 'AL'],
        [0x1_0F00, 0x1_0F2F, 'R'],
        [0x1_0F30, 0x1_0F6F, 'AL'],
        [0x1_0F70, 0x1_0FFF, 'R'],
        [0x1_E800, 0x1_EC6F, 'R'],
        [0x1_EC70, 0x1_ECBF, 'AL'],
        [0x1_ECC0, 0x1_ECFF, 'R'],
        [0x1_ED00, 0x1_ED4F, 'AL'],
        [0x1_ED50, 0x1_EDFF, 'R'],
        [0x1_EE00, 0x1_EEFF, 'AL'],
        [0x1_EF00, 0x1_EFFF, 'R'],
    ];

    /**
     * Get the bidirectional type of a Unicode code point.
     *
     * @param int $ord Unicode code point.
     */
    public static function getType(int $ord): string
    {
        if (isset(self::UNI[$ord])) {
            return self::UNI[$ord];
        }

        if ($ord < 0x0590 || $ord > 0x1_EFFF) {
            return 'L';
        }

        foreach (self::DEFAULT_RANGES as [$first, $last, $type]) {
            if ($ord < $first) {
                break;
            }

            if ($ord <= $last) {
                return $type;
            }
        }

        return 'L';
    }

    /**
     * Get the bidirectional class of a Unicode code point.
     *
     * Returns null for the explicit formatting codes
     * (LRE, LRO, RLE, RLO, PDF, LRI, RLI, FSI, PDI).
     *
     * @param int $ord Unicode code point.
     */
    public static function getBidiClass(int $ord): ?BidiClass
    {
        return BidiClass::tryFrom(self::getType($ord));
    }
